def arrayNesting(A):
    visited = [False] * len(A)
    max_length = 0

    for i in range(len(A)):
        if not visited[i]:
            current = i
            length = 0
            while not visited[current]:
                visited[current] = True
                current = A[current]
                length += 1
            max_length = max(max_length, length)

    return max_length
